// Let only articles through whose URL we have not seen before.
// Seen URLs live in workflow static data, which only persists in production runs.
const staticData = $getWorkflowStaticData('global');
const seen = staticData.seenUrls || [];
const newItems = $input.all().filter(item => item.json.url && !seen.includes(item.json.url));
staticData.seenUrls = seen.concat(newItems.map(item => item.json.url)).slice(-500);
return newItems;

// Build one digest email out of all new articles.
const escapeHtml = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const items = $input.all();
const lines = items.map(item => {
  const date = item.json.date ? ` (${escapeHtml(item.json.date)})` : '';
  return `<li><a href="${escapeHtml(item.json.url)}">${escapeHtml(item.json.title)}</a>${date}</li>`;
});
const count = items.length;
return [{ json: {
  subject: `${count} new article${count === 1 ? '' : 's'} on your watched page`,
  html: `<p>New articles since the last check:</p>\n<ul>\n${lines.join('\n')}\n</ul>`
} }];
